1	//! The `commit` subcommand: make a rung's commit pair, one commit
2	//! per repo of a dual workspace, each stamped with the other's
3	//! change id, before anything is pushed.
4	//!
5	//! The pair is what the per-rung flow reviews: the description and
6	//! the diff together, as a commit, by `jj show @-` in either repo.
7	//! Nothing here reaches a remote, so a fix after the review is a
8	//! fold into the pair and never a remote rewrite, and `vc-x1 push`
9	//! has nothing left to write: it publishes what was reviewed.
10	//!
11	//! - `-s b` makes both commits now. Both change ids are known
12	//!   before either is made, since a jj commit keeps the working
13	//!   copy's change id, so each trailer is written once and never
14	//!   predicted or restamped.
15	//! - `-s w` makes the work commit now, its trailer naming the agent
16	//!   `@` all the same, and leaves the agent half to `push`, which
17	//!   commits the journal as the partner. The pair is then made in
18	//!   two steps, and the review's own transcript lands in the rung's
19	//!   agent commit.
20	//! - `-s a` is refused: an agent commit made first names a work `@`
21	//!   that push would then commit with a trailer of its own, so that
22	//!   direction is where an unpaired commit is real.
23	//! - `-s p` commits a plain repo with the title and body and no
24	//!   trailer, the same description discipline on a repo with no
25	//!   partner.
26	//! - `--body` is the text, or `@PATH` to read it from a file, since
27	//!   a body in commit-body form has markers and blank lines a shell
28	//!   quote mangles.
29	//! - The work side's `@` must hold a change, since a rung changes
30	//!   the work repo. The agent side's `@` is the session's journal
31	//!   and is committed as it stands.
32	//! - `--closing` makes the work commit the cycle's merge close-out:
33	//!   `@`, the closing's edits, is first given `main` and the last
34	//!   rung as its parents, in that order, the trunk first, by the
35	//!   primitive `vc-x1 merge` uses, then committed, which keeps
36	//!   them. `main` is
37	//!   wherever it is now, so one that moved during the cycle is
38	//!   joined by the merge rather than needing a rebase.
39	//!   The title's " closing" or " dead-end closing" suffix is checked
40	//!   against the flag both ways, never its trigger.
41	//! - A failure after the first commit restores both repos from the
42	//!   `jj op` snapshots taken just before it, as push does inside its
43	//!   mutation window.
44	
45	use std::path::{Path, PathBuf};
46	
47	use clap::Args;
48	use log::{debug, info};
49	
50	use crate::context::Context;
51	use crate::desc_helpers::{ochid_prefix_for, with_trailer};
52	use crate::jj;
53	use crate::options_flags::dry_run::DryRunFlag;
54	use crate::options_flags::scope::{REPO_SCOPE_FORMS, RepoScope, repo_scope_parser};
55	use crate::pair::{Pair, Snapshots, resolve_pair};
56	use crate::subcommand::SubcommandRunner;
57	
58	/// Commit the working copies as a rung's pair, or a plain repo's
59	/// commit, with the given title and body.
60	#[derive(Args, Debug)]
61	pub struct CommitArgs {
62	    /// Where: a path in the workspace for `-s b|w`, its root or
63	    /// either repo, or the repo itself for `-s p` [default: the
64	    /// current directory]
65	    #[arg(short = 'R', long, value_name = "PATH")]
66	    pub repo: Option<PathBuf>,
67	
68	    /// Which repos, required: `b|both` makes both commits now,
69	    /// `w|work` the work half with the agent half left to push,
70	    /// `p|por` a plain repo's commit, and `a` is refused
71	    #[arg(
72	        short = 's',
73	        long,
74	        value_name = "SCOPE",
75	        value_parser = repo_scope_parser(&["work", "both", "por"]),
76	        required = true,
77	        help = format!("Which repos, required: {REPO_SCOPE_FORMS}, `a` refused")
78	    )]
79	    pub scope: RepoScope,
80	
81	    /// Commit title, the Conventional Commit line
82	    #[arg(long, value_name = "STR", required = true)]
83	    pub title: String,
84	
85	    /// Commit body, the problem and its solutions, or @PATH to read
86	    /// it from a file
87	    #[arg(long, value_name = "STR|@PATH", required = true)]
88	    pub body: String,
89	
90	    /// Make the work commit the cycle's closing, the merge of the
91	    /// trunk and the ladder; the title must end " closing"
92	    #[arg(long)]
93	    pub closing: bool,
94	
95	    /// Print the descriptions it would write, trailers included, and
96	    /// commit nothing
97	    #[command(flatten)]
98	    pub dry_run: DryRunFlag,
99	}
100	
101	/// Refuse a title whose closing suffix disagrees with `--closing`:
102	/// the flag decides, and the title is transcribed text the check
103	/// catches a slip in. A " closing" title without the flag is a slip
104	/// only when there is a ladder to close: with the work `@-` on
105	/// `main`, a single-step cycle's, it is just a title.
106	fn check_closing_title(title: &str, closing: bool, has_ladder: bool) -> Result<(), String> {
107	    let says_closing = title.trim_end().ends_with(" closing");
108	    if closing && !says_closing {
109	        return Err(format!(
110	            "commit --closing: the title '{title}' does not end \" closing\" or \" dead-end \
111	             closing\", the cycle's closing bookend"
112	        ));
113	    }
114	    if !closing && says_closing && has_ladder {
115	        return Err(format!(
116	            "commit: the title '{title}' ends \" closing\", so it is the cycle's closing \
117	             bookend: pass --closing to make it the merge of the trunk and the ladder"
118	        ));
119	    }
120	    Ok(())
121	}
