218	/// Entry point: the pair, or the plain commit.
219	pub fn commit(ctx: &mut Context, params: &CommitParams) -> Result<(), Box<dyn std::error::Error>> {
220	    debug!("commit: enter {params:?}");
221	    match &params.target {
222	        Target::Pair { pair, agent_now } => commit_pair(ctx, pair, *agent_now, params),
223	        Target::Por(repo) => commit_por(ctx, repo, params),
224	    }
225	}
226	
227	/// Refuse a repo that cannot take the commit: a conflicted one, or
228	/// for the work side an empty `@`, since a rung changes the work
229	/// repo and an empty commit would carry a trailer naming nothing
230	/// worth reviewing.
231	fn preflight(
232	    repo: &Path,
233	    label: &str,
234	    must_change: bool,
235	) -> Result<(), Box<dyn std::error::Error>> {
236	    crate::pair::refuse_conflicts(repo, "commit", label)?;
237	    if must_change && jj::is_empty(repo, "@")? {
238	        return Err(format!(
239	            "commit: nothing to commit, the {label} repo's @ is empty ('{}')",
240	            repo.display()
241	        )
242	        .into());
243	    }
244	    Ok(())
245	}
246	
247	/// Make the pair: both change ids read from the working copies
248	/// first, then the work commit with the agent's id in its trailer
249	/// and, with `agent_now`, the agent commit with the work's id in
250	/// its own. Without it the agent `@` is left for push to commit as
251	/// the partner, its id already in the work commit's trailer.
252	fn commit_pair(
253	    ctx: &mut Context,
254	    pair: &Pair,
255	    agent_now: bool,
256	    params: &CommitParams,
257	) -> Result<(), Box<dyn std::error::Error>> {
258	    let (work, agent) = (pair.work.as_path(), pair.agent.as_path());
259	    preflight(work, "work", true)?;
260	    preflight(agent, "agent", false)?;
261	    check_closing(params, work)?;
262	    let work_chid = jj::chid_of(work, "@")?;
263	    let agent_chid = jj::chid_of(agent, "@")?;
264	    let agent_prefix = ochid_prefix_for(agent)?;
265	    let text = format!("{}\n\n{}", params.title, params.body);
266	    let work_desc = with_trailer(&text, &format!("{agent_prefix}{agent_chid}"));
267	    let agent_desc = with_trailer(&text, &format!("/{work_chid}"));
268	    let merge = if params.closing {
269	        Some(closing_parents(work)?)
270	    } else {
271	        None
272	    };
273	
274	    if params.dry_run {
275	        if let Some((base, tip)) = &merge {
276	            info!(
277	                "commit: [dry-run] the work commit is the merge of the fork point {base} and the last rung {tip}"
278	            );
279	        }
280	        info!(
281	            "commit: [dry-run] the work commit {work_chid}, in {}:\n{work_desc}",
282	            work.display()
283	        );
284	        if agent_now {
285	            info!(
286	                "commit: [dry-run] the agent commit {agent_chid}, in {}:\n{agent_desc}",
287	                agent.display()
288	            );
289	        } else {
290	            info!(
291	                "commit: [dry-run] the agent @ {agent_chid} is left for push to commit as the partner"
292	            );
293	        }
294	        return Ok(());
295	    }
296	    let snapshots = Snapshots::take(pair)?;
297	    if let Some((base, tip)) = &merge
298	        && let Err(e) = make_closing_merge(ctx, work, base, tip)
299	    {
300	        snapshots.restore(pair, "commit", e.as_ref());
301	        return Err(e);
302	    }
303	    info!("commit work: {} -> @- {work_chid}", work.display());
304	    if let Err(e) = ctx.session(work)?.commit(&work_desc) {
305	        snapshots.restore(pair, "commit", e.as_ref());
306	        return Err(e);
307	    }
308	    if !agent_now {
309	        info!(
310	            "commit: the work half is made, its trailer naming the agent @ {agent_chid}, which \
311	             push commits as the partner. Review it with `jj show @- -R {}`",
312	            work.display()
313	        );
314	        return Ok(());
315	    }
316	    info!("commit agent: {} -> @- {agent_chid}", agent.display());
317	    if let Err(e) = ctx.session(agent)?.commit(&agent_desc) {
318	        snapshots.restore(pair, "commit", e.as_ref());
319	        return Err(e);
320	    }
321	    info!(
322	        "commit: the pair is made, review it with `jj show @- -R {}` and `jj show @- -R {}`",
323	        work.display(),
324	        agent.display()
325	    );
326	    Ok(())
327	}
