710	                    agent: fx.bot.clone(),
711	                },
712	                sides: crate::options_flags::scope::Scope(vec![
713	                    crate::options_flags::scope::Side::Work,
714	                    crate::options_flags::scope::Side::Bot,
715	                ]),
716	            },
717	            text: None,
718	            dry_run: false,
719	        };
720	        crate::squash::squash(&mut test_ctx(), &fold).expect("the fix folds");
721	        assert_eq!(
722	            parents(&fx.work, "@-"),
723	            [base, tip],
724	            "the squash kept both parents"
725	        );
726	        assert!(jj_ok(&fx.work, &["file", "list", "-r", "@-"]).contains("fix.txt"));
727	    }
728	
729	    /// A `main` that moved during the cycle is joined by the closing:
730	    /// its first parent is `main` as it is now, and its tree carries
731	    /// what `main` gained, with no rebase of the ladder first.
732	    #[test]
733	    fn closing_joins_a_main_that_moved() {
734	        let fx = Fixture::new("commit-closing-moved");
735	        for rung in ["one", "two"] {
736	            fs::write(fx.work.join(format!("{rung}.txt")), rung).expect("write");
737	            jj_ok(&fx.work, &["commit", "-m", &format!("feat: rung {rung}")]);
738	        }
739	        let tip = commit_id(&fx.work, "@-");
740	        jj_ok(&fx.work, &["new", "main"]);
741	        fs::write(fx.work.join("landed.txt"), "another cycle\n").expect("write");
742	        jj_ok(&fx.work, &["commit", "-m", "feat: another cycle landed"]);
743	        jj_ok(&fx.work, &["bookmark", "set", "main", "-r", "@-"]);
744	        let moved = commit_id(&fx.work, "main");
745	        jj_ok(&fx.work, &["new", &tip]);
746	        fs::write(fx.work.join("closing.txt"), "closing\n").expect("write");
747	
748	        let mut a = args("w", &fx.work);
749	        a.title = "feat: a cycle closing".to_string();
750	        a.closing = true;
751	        let params = CommitParams::try_from(&a).expect("params");
752	        commit(&mut test_ctx(), &params).expect("the closing is made");
753	
754	        assert_eq!(parents(&fx.work, "@-"), [moved, tip]);
755	        let files = jj_ok(&fx.work, &["file", "list", "-r", "@-"]);
756	        for f in ["one.txt", "two.txt", "landed.txt", "closing.txt"] {
757	            assert!(files.contains(f), "{f} missing:\n{files}");
758	        }
759	    }
760	
761	    /// `--closing` with no ladder, the work `@-` on `main`, is refused
762	    /// before anything is committed.
763	    #[test]
764	    fn closing_with_no_ladder_is_refused() {
765	        let fx = Fixture::new("commit-closing-none");
766	        fs::write(fx.work.join("closing.txt"), "closing\n").expect("write");
767	        let work_at = chid(&fx.work, "@");
768	        let mut a = args("b", &fx.work);
769	        a.title = "feat: a cycle closing".to_string();
770	        a.closing = true;
771	        let params = CommitParams::try_from(&a).expect("params");
772	        let err = commit(&mut test_ctx(), &params)
773	            .expect_err("no ladder")
774	            .to_string();
775	        assert!(err.contains("no ladder"), "{err}");
776	        assert_eq!(chid(&fx.work, "@"), work_at, "nothing was committed");
777	    }
778	
779	    /// An empty work `@` is nothing to commit, and the agent repo is
780	    /// left as it was.
781	    #[test]
782	    fn an_empty_work_at_is_refused_before_anything_is_committed() {
783	        let fx = Fixture::new("commit-empty");
784	        fs::write(fx.bot.join("session.jsonl"), "{\"line\":1}\n").expect("write");
785	        let agent_at = chid(&fx.bot, "@");
786	        let params = CommitParams::try_from(&args("b", &fx.work)).expect("params");
787	        let err = commit(&mut test_ctx(), &params)
788	            .expect_err("nothing to commit")
789	            .to_string();
790	        assert!(err.contains("nothing to commit"), "{err}");
791	        assert_eq!(chid(&fx.bot, "@"), agent_at, "the agent @ is untouched");
792	    }
793	
794	    /// `-s p` commits a plain repo with the description and no
795	    /// trailer.
796	    #[test]
797	    fn por_commits_without_a_trailer() {
798	        let fx = FixturePor::new("commit-por");
799	        fs::write(fx.work.join("plain.txt"), "plain\n").expect("write");
800	        let params = CommitParams::try_from(&args("p", &fx.work)).expect("params");
801	        commit(&mut test_ctx(), &params).expect("the plain commit is made");
802	        let desc = description(&fx.work, "@-");
803	        assert!(desc.starts_with("feat: a rung\n\nThe problem."), "{desc}");
804	        assert!(!desc.contains("ochid:"), "{desc}");
805	    }
806	}
