329	/// The closing check, asked only when the flag or the title names a
330	/// closing, since the ladder question needs a `main`, which a plain
331	/// repo need not have.
332	fn check_closing(params: &CommitParams, repo: &Path) -> Result<(), Box<dyn std::error::Error>> {
333	    if params.closing || params.title.trim_end().ends_with(" closing") {
334	        check_closing_title(&params.title, params.closing, has_ladder(repo)?)?;
335	    }
336	    Ok(())
337	}
338	
339	/// Whether the work `@-` is a ladder above `main`, one a closing
340	/// closes: not `main` and not contained in it.
341	fn has_ladder(repo: &Path) -> Result<bool, Box<dyn std::error::Error>> {
342	    Ok(!jj::matches(repo, "@- & ::main")?)
343	}
344	
345	/// The closing's two sources, as commit ids read before anything
346	/// moves: `main` first, wherever it is now, so a `main` that moved
347	/// during the cycle is joined by the merge rather than needing a
348	/// rebase, and the last rung, the work `@-`, second. Refused when
349	/// there is no ladder, the last rung being in `main` already.
350	fn closing_parents(repo: &Path) -> Result<(String, String), Box<dyn std::error::Error>> {
351	    if !has_ladder(repo)? {
352	        return Err(
353	            "commit --closing: the work @- is in `main`, so there is no ladder to close. \
354	                    A closing is made on the cycle's last rung"
355	                .into(),
356	        );
357	    }
358	    Ok((jj::cid_of(repo, "main")?, jj::cid_of(repo, "@-")?))
359	}
360	
361	/// Merge `main` and the last rung into `@`, the closing's edits,
362	/// setting them as `@`'s parents in that order, the trunk first,
363	/// which `vc-x1 merge`'s append would not, before the commit, which
364	/// keeps `@`'s parents.
365	fn make_closing_merge(
366	    ctx: &mut Context,
367	    repo: &Path,
368	    base: &str,
369	    tip: &str,
370	) -> Result<(), Box<dyn std::error::Error>> {
371	    info!("commit work: the closing merges {base} and {tip} into @");
372	    crate::merge::set_parents(
373	        ctx,
374	        repo,
375	        "@",
376	        &[base.to_string(), tip.to_string()],
377	        "commit",
378	    )?;
379	    Ok(())
380	}
381	
382	/// Commit a plain repo with the description and no trailer.
383	fn commit_por(
384	    ctx: &mut Context,
385	    repo: &Path,
386	    params: &CommitParams,
387	) -> Result<(), Box<dyn std::error::Error>> {
388	    preflight(repo, "plain", true)?;
389	    check_closing(params, repo)?;
390	    let chid = jj::chid_of(repo, "@")?;
391	    let desc = format!("{}\n\n{}", params.title, params.body);
392	    let merge = if params.closing {
393	        Some(closing_parents(repo)?)
394	    } else {
395	        None
396	    };
397	    if params.dry_run {
398	        if let Some((base, tip)) = &merge {
399	            info!("commit: [dry-run] the merge of the fork point {base} and the last rung {tip}");
400	        }
401	        info!(
402	            "commit: [dry-run] the commit {chid}, in {}:\n{desc}",
403	            repo.display()
404	        );
405	        return Ok(());
406	    }
407	    let snapshot = crate::pair::Snapshot::take(repo)?;
408	    if let Some((base, tip)) = &merge
409	        && let Err(e) = make_closing_merge(ctx, repo, base, tip)
410	    {
411	        snapshot.restore("commit", e.as_ref());
412	        return Err(e);
413	    }
414	    info!("commit: {} -> @- {chid}", repo.display());
415	    if let Err(e) = ctx.session(repo)?.commit(&desc) {
416	        snapshot.restore("commit", e.as_ref());
417	        return Err(e);
418	    }
419	    Ok(())
420	}
