/// `--closing` merges a ladder of any length, the opening alone
/// included, which still closes as a ladder: the merge's parents
/// are `main` and the last rung, and its tree carries every rung
/// and the closing's edits.
#[test]
fn closing_merges_a_ladder_of_one_two_or_three_rungs() {
    for len in 1..=3 {
        let fx = Fixture::new(&format!("commit-closing-{len}"));
        let base = commit_id(&fx.work, "main");
        let rungs: Vec<String> = (1..=len).map(|n| format!("rung{n}")).collect();
        for rung in &rungs {
            fs::write(fx.work.join(format!("{rung}.txt")), rung).expect("write");
            jj_ok(&fx.work, &["commit", "-m", &format!("feat: {rung}")]);
        }
        let tip = commit_id(&fx.work, "@-");
        fs::write(fx.work.join("closing.txt"), "closing\n").expect("write");
        fs::write(fx.bot.join("session.jsonl"), "{\"line\":1}\n").expect("write");

        let mut a = args("b", &fx.work);
        a.title = "feat: a cycle closing".to_string();
        a.closing = true;
        let params = CommitParams::try_from(&a).expect("params");
        commit(&mut test_ctx(), &params).expect("the closing is made");

        assert_eq!(parents(&fx.work, "@-"), [base, tip], "a ladder of {len}");
        let files = jj_ok(&fx.work, &["file", "list", "-r", "@-"]);
        for f in rungs
            .iter()
            .map(|r| format!("{r}.txt"))
            .chain(["closing.txt".to_string()])
        {
            assert!(files.contains(&f), "a ladder of {len}: {f} missing:\n{files}");
        }
    }
}

/// `--closing` with no ladder, the work `@-` on `main`, makes a
/// single-step cycle's one commit: plain, its one parent `main`,
/// under the bare cycle title, which needs no " closing", and
/// paired with the agent commit as any rung is.
#[test]
fn closing_with_no_ladder_is_the_single_step_commit() {
    let fx = Fixture::new("commit-closing-none");
    let base = commit_id(&fx.work, "main");
    fs::write(fx.work.join("change.txt"), "the one commit\n").expect("write");
    fs::write(fx.bot.join("session.jsonl"), "{\"line\":1}\n").expect("write");
    let work_at = chid(&fx.work, "@");
    let agent_at = chid(&fx.bot, "@");
    let mut a = args("b", &fx.work);
    a.title = "feat: a cycle".to_string();
    a.closing = true;
    let params = CommitParams::try_from(&a).expect("params");
    commit(&mut test_ctx(), &params).expect("the single-step commit is made");

    assert_eq!(parents(&fx.work, "@-"), [base], "one parent, `main`");
    assert_eq!(chid(&fx.work, "@-"), work_at);
    let desc = description(&fx.work, "@-");
    assert!(desc.starts_with("feat: a cycle\n\n"), "{desc}");
    assert!(
        desc.trim_end()
            .ends_with(&format!("ochid: /.claude/{agent_at}")),
        "{desc}"
    );
    assert_eq!(chid(&fx.bot, "@-"), agent_at, "the agent commit is made");
}

